import{_ as i,o as a,c as s,a3 as o}from"./chunks/framework.IBRwS0-4.js";const h=JSON.parse('{"title":"Decisions","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/decisions.md","filePath":"explanation/decisions.md"}'),r={name:"explanation/decisions.md"};function n(t,e,c,l,d,m){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h1><p>ADR-lite: the load-bearing decisions, each with the alternative it beat and the consequence it carries.</p><h2 id="mechanism-vs-policy" tabindex="-1">Mechanism vs policy <a class="header-anchor" href="#mechanism-vs-policy" aria-label="Permalink to &quot;Mechanism vs policy&quot;">​</a></h2><p><strong>Decision:</strong> sepia owns everything you can do <em>to</em> a session; peregrin owns <em>who/when/where</em>. The seam is <code>sepia serve</code> — ndjson JSON-RPC over stdio — so orchestrators never link session internals.</p><ul><li><em>Alternative:</em> one crate doing both, or orchestrators linking <code>sepia-session</code> directly.</li><li><em>Consequence:</em> policy evolves fast without touching mechanism; mechanism stays boring (stable IR, tolerant parsers). Cost: a subprocess hop per session op.</li></ul><h2 id="drivers-are-binaries-not-libraries" tabindex="-1">Drivers are binaries, not libraries <a class="header-anchor" href="#drivers-are-binaries-not-libraries" aria-label="Permalink to &quot;Drivers are binaries, not libraries&quot;">​</a></h2><p><strong>Decision:</strong> store adapters ship as <code>sepia-driver-&lt;id&gt;</code> executables discovered at runtime (<code>$SEPIA_DRIVER_DIR</code>, data dir, <code>/usr/local/lib/sepia/drivers</code>, PATH).</p><ul><li><em>Alternative:</em> in-process adapter crates behind a trait.</li><li><em>Consequence:</em> a crashed or hung adapter kills a subprocess, not your daemon; adding an agent is dropping a binary in a dir. Cost: serialization overhead and a second protocol to version.</li></ul><h2 id="one-canonical-ir-lossy-edges-marked" tabindex="-1">One canonical IR, lossy edges marked <a class="header-anchor" href="#one-canonical-ir-lossy-edges-marked" aria-label="Permalink to &quot;One canonical IR, lossy edges marked&quot;">​</a></h2><p><strong>Decision:</strong> every agent store maps onto one session IR; what a store can&#39;t express is flagged <code>lossy</code> in metadata.</p><ul><li><em>Alternative:</em> per-agent native models with translation at the edges.</li><li><em>Consequence:</em> one read/write path serves every agent and conversion is IR→IR; the audit trail shows exactly what was dropped.</li></ul><h2 id="the-sepia-command-is-a-tamias-shim" tabindex="-1">The <code>sepia</code> command is a tamias shim <a class="header-anchor" href="#the-sepia-command-is-a-tamias-shim" aria-label="Permalink to &quot;The `sepia` command is a tamias shim&quot;">​</a></h2><p><strong>Decision:</strong> no hand-rolled <code>sepia</code> binary — <code>libraries/sepia</code> declares <code>bins: [{name: sepia, shim: cli, driver: sepia}]</code> over <code>tamias-driver-sepia</code>, whose ops manifest derives from the clap tree.</p><ul><li><em>Alternative:</em> a <code>[[bin]]</code> in <code>sepia-cli</code> plus bespoke install logic.</li><li><em>Consequence:</em> one distribution path for every org tool; bounded verbs become ops, <code>serve</code> stays a surface. Cost: the command requires tamias installed.</li></ul><h2 id="blocking-turn-as-a-wire-primitive" tabindex="-1">Blocking turn as a wire primitive <a class="header-anchor" href="#blocking-turn-as-a-wire-primitive" aria-label="Permalink to &quot;Blocking turn as a wire primitive&quot;">​</a></h2><p><strong>Decision:</strong> <code>sessions.prompt_wait</code> blocks until terminal state inside the service, with concurrent dispatch so <code>cancel</code>/ <code>permission</code> interleave.</p><ul><li><em>Alternative:</em> prompt returns immediately; callers poll events.</li><li><em>Consequence:</em> orchestrators get a synchronous turn boundary without reimplementing event correlation; the entity-plane <code>sepia.prompt_wait</code> op carries the same capability.</li></ul>',17)])])}const u=i(r,[["render",n]]);export{h as __pageData,u as default};
